<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Taxonomy\Service\ListTaxonomyDuplicateSuggestionsService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class TaxonomyDuplicateSuggestionController { public function __construct(private readonly AuthService $auth,private readonly ListTaxonomyDuplicateSuggestionsService $suggestions,private readonly ApiResponseFactory $responses){} public function list(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access):ResponseInterface{try{$user=$this->auth->currentUser($access);}catch(DomainException|UnavailableUserException){return $this->responses->problem($response,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$request->getAttribute('request_id'));}if(!in_array('ADMIN',$user->roles,true))return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));return $this->responses->success($response,$this->suggestions->list(),(string)$request->getAttribute('request_id'));} }
